// parse_rustc_main.rs - Parse the real rustc main function
// Generated by step4_bootstrap - Parse Real Rustc Main

use split_decls_genesis::{extract_all_symbols_from_file_fast};

fn main() {
    println!("🔍 Parsing the REAL rustc main function...");
    
    let rustc_main_file = "../rust/compiler/rustc/src/main.rs";
    println!("📄 Parsing: {}", rustc_main_file);
    
    match extract_all_symbols_from_file_fast(rustc_main_file, "rustc") {
        Ok(symbols) => {
            println!("✅ Extracted {} symbols from rustc main.rs", symbols.len());
            
            // Look for main function specifically
            if let Some(main_fn) = symbols.iter().find(|s| s.name == "main") {
                println!("\n🎯 FOUND REAL RUSTC MAIN:");
                println!("  Function: {}", main_fn.name);
                println!("  Type: {}", main_fn.symbol_type);
                println!("  File: {}", main_fn.source_file);
                println!("  Dependencies ({}): {:?}", main_fn.dependencies.len(), main_fn.dependencies);
                
                // Analyze each dependency
                println!("\n🔍 DEPENDENCY ANALYSIS:");
                for (i, dep) in main_fn.dependencies.iter().enumerate() {
                    println!("  {}. {}", i+1, dep);
                    
                    // Analyze what each dependency is
                    match dep.as_str() {
                        d if d.starts_with("target_") => println!("     → Cfg attribute (compile-time constant)"),
                        d if d.contains("::") => println!("     → Qualified path (module::function)"),
                        d if d == "conditional_expr" => println!("     → AST expression classification"),
                        d if d.starts_with("attr_") => println!("     → Attribute dependency"),
                        _ => println!("     → Unknown dependency type"),
                    }
                }
            } else {
                println!("❌ Main function NOT found in rustc main.rs");
            }
            
            // Show all functions found
            let functions: Vec<_> = symbols.iter()
                .filter(|s| s.symbol_type.starts_with("fn"))
                .collect();
            
            println!("\n📋 All functions found ({}):", functions.len());
            for func in functions {
                println!("  - {}: {}", func.name, func.symbol_type);
            }
            
            // Show all symbols
            println!("\n📋 All symbols found ({}):", symbols.len());
            for symbol in &symbols {
                println!("  - {}: {} (deps: {})", symbol.name, symbol.symbol_type, symbol.dependencies.len());
            }
            
        },
        Err(e) => {
            println!("❌ Failed to parse rustc main.rs: {}", e);
        }
    }
}
